def resolve(path, cwd, links):
    """
    Resolve a path to its canonical absolute path, following symlinks.

    Args:
        path: The path to resolve (absolute or relative to cwd)
        cwd: Current working directory (canonical absolute path)
        links: Dict mapping canonical absolute paths to symlink targets

    Returns:
        The canonical absolute path, or None on error
    """

    def _resolve_helper(path, cwd, links, link_count):
        """Helper function that tracks link count across recursion."""

        # Convert relative path to absolute
        if not path.startswith('/'):
            if cwd == '/':
                current = path
            else:
                current = cwd + '/' + path
        else:
            current = path

        # Split into components and process left to right
        components = current.split('/')

        # Start with root
        resolved = []

        for i, component in enumerate(components):
            # Skip empty components and '.'
            if not component or component == '.':
                continue

            # Handle '..'
            if component == '..':
                if resolved:
                    resolved.pop()
                # If at root, '..' stays at root
                continue

            # Any other name is appended
            resolved.append(component)

            # Build current path
            current_path = '/' + '/'.join(resolved)

            # Check if this path is a symlink
            if current_path in links:
                link_count[0] += 1
                if link_count[0] > 8:
                    return None

                # Get the symlink target
                target = links[current_path]

                # Get remaining components after this one
                remaining = components[i + 1:]

                # Build the full path to resolve: target + remaining
                if remaining:
                    remaining_str = '/'.join(remaining)
                    if target.startswith('/'):
                        resolve_path = target + '/' + remaining_str
                    else:
                        # Target is relative to the directory containing the link
                        link_dir = '/'.join(resolved[:-1])
                        if link_dir:
                            link_dir = '/' + link_dir
                        else:
                            link_dir = '/'
                        resolve_path = link_dir + '/' + target + '/' + remaining_str
                else:
                    if target.startswith('/'):
                        resolve_path = target
                    else:
                        # Target is relative to the directory containing the link
                        link_dir = '/'.join(resolved[:-1])
                        if link_dir:
                            link_dir = '/' + link_dir
                        else:
                            link_dir = '/'
                        resolve_path = link_dir + '/' + target

                # Recursively resolve
                return _resolve_helper(resolve_path, cwd, links, link_count)

        # Build final path
        if not resolved:
            return '/'

        final_path = '/' + '/'.join(resolved)
        return final_path

    link_count = [0]  # Use list to allow modification in nested function
    return _resolve_helper(path, cwd, links, link_count)

